def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def is_seq(x):
        return isinstance(x, (list, tuple))

    def pos(obj, default=(0, 0)):
        if is_seq(obj) and len(obj) >= 2:
            try:
                return int(obj[0]), int(obj[1])
            except Exception:
                return default
        return default

    def clamp_move(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def md(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def first_nonempty(d, keys):
        for k in keys:
            v = d.get(k, []) if isinstance(d, dict) else []
            if v:
                return v
        return []

    obs = observation if isinstance(observation, dict) else {}
    env = obs.get("environment_name", "")
    sx, sy = pos(obs.get("self_position", (0, 0)), (0, 0))
    ox, oy = pos(obs.get("opponent_position", (sx, sy)), (sx, sy))
    w = obs.get("grid_width", 0) or 0
    h = obs.get("grid_height", 0) or 0
    maxx = max(0, int(w) - 1) if isinstance(w, int) else 0
    maxy = max(0, int(h) - 1) if isinstance(h, int) else 0

    if env == "pursuit_evasion":
        role = obs.get("self_role", "pursuer")
        if role == "pursuer":
            return clamp_move((sx, sy), (ox, oy))
        corners = [(0, 0), (0, maxy), (maxx, 0), (maxx, maxy)]
        target = max(corners, key=lambda c: md(c, (ox, oy)))
        return clamp_move((sx, sy), target)

    if env == "territory_control":
        targets = first_nonempty(obs, ("frontier_cells", "unclaimed_cells", "target_cells", "opponent_territory"))
        if targets:
            best = min((pos(c, (sx, sy)) for c in targets), key=lambda c: md(c, (sx, sy)))
            return clamp_move((sx, sy), best)
        if (sx, sy) != (ox, oy):
            return [sgn(ox - sx), sgn(oy - sy)]
        return [0, 0]

    resources = first_nonempty(obs, ("resources", "resource_positions", "targets", "food", "collectibles"))
    if resources:
        best = min((pos(c, (sx, sy)) for c in resources), key=lambda c: md(c, (sx, sy)))
        return clamp_move((sx, sy), best)

    allies = first_nonempty(obs, ("allied_positions", "teammate_positions", "team_positions"))
    if allies:
        tx, ty = pos(allies[0], (sx, sy))
        if (tx, ty) != (sx, sy):
            return clamp_move((sx, sy), (tx, ty))

    if (sx, sy) != (ox, oy):
        return [sgn(ox - sx), sgn(oy - sy)]
    return [0, 0]

